save(72,dict(paragraphs=["Mukul Mishra is an Odia poet from Bolangir. Her collections include Apoorna, Meghamanaa and Maayalagna; Rupasi, published by Black Eagle Books, is a long poem in thirty-six sections. Sahitya Akademi’s record of its 2014 Asmita programme in Bolangir places her among the participating Odia women writers who read their work.","Her Kabita Live poems bring night, light and household life into close conversation. ‘ରାତି’ moves through sleeplessness and unsettling imaginings towards the small preparations of a kitchen and another dawn. In ‘ଭଉଁରି-୨୧’, lamps, fireworks and a moth’s attraction to flame reveal how illumination can carry tenderness and pain together. A mother’s presence gives those images their emotional centre."],sources=[source('Sahitya Akademi — July–August 2014 newsletter, Asmita programme','https://sahitya-akademi.gov.in/e-newsletter/July-August_2014_NewsLetter.pdf',['Mukul Mishra among Odia women poets reading at Bolangir on 5 July 2014'],'opened_pdf_text'),source('Black Eagle Books — poetry catalogue, Rupasi','https://www.blackeaglebooks.org/product-category/poetry/page/11/?layout=list&per_page=18',['Rupasi author and thirty-six sections; earlier three collections and publisher Paschima'],'search_index_excerpt'),source('OrissaPOST — Sound of silent verses','https://www.orissapost.com/sound-of-silent-verses/amp/',['Bolangir; poet and collections; interview identifies her as a woman'],'search_index_excerpt')],identity_match='Captured Odia woman poet from Bolangir matches institutional women-writers event and interview location, with publisher bibliography corroboration. Unrelated English-name search results excluded.',poems_read=[dict(id=37,title='ରାତି',basis='Full original Odia text; night, imagined mortality and kitchen preparations. Speaker is not a biographical health record.'),dict(id=496,title='ଭଉଁରି-୨୧',basis='Full original Odia text; mother, fireworks, lamp, moth, light and burning.')],limitations=['Collection totals vary across dated biographies; no current total asserted.','Publisher catalogue and interview available through indexed text; direct retrieval failed.','Rupasi individual bookseller page returned cache miss; no unverified reader book link added.','No personal circumstances inferred from poem speakers.'],research_leads=[dict(url='https://www.theportobellobookshop.com/9781645600077',access='catalogue opened; product cache miss',finding='Catalogue verifies title and author; individual destination not retrievable.'),dict(url='https://odishapostepaper.com/uploads/epaper/2024-06/6680a69bb0f05.pdf',access='search_index_excerpt',finding='June 2024 profile has six collections compared with five in captured biography; totals omitted rather than treated as contradiction in identity.')],next_action='Author/editor review; confirm preferred title transliterations and a working direct book destination.'))
